{
  "states": [
    "LISTEN",
    "REQUEST",
    "RESPOND",
    "PARTOPEN",
    "OPEN",
    "CLOSEREQ",
    "CLOSING",
    "TIMEWAIT"
  ],
  "transitions": [
    {
      "from": "LISTEN",
      "event": "P.type == Request or P contains a valid Init Cookie option",
      "action": "Set S := new socket for this port pair, S.state = RESPOND, Choose S.ISS or set from Init Cookies, Initialize S.GAR := S.ISS, Set S.ISR, S.GSR, S.SWL, S.SWH from packet or Init Cookies",
      "to": "RESPOND"
    },
    {
      "from": "LISTEN",
      "event": "P.type != Request and P does not contain a valid Init Cookie option",
      "action": "Generate Reset(No Connection) unless P.type == Reset",
      "to": "LISTEN"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Response or P.type == Reset and S.AWL <= P.ackno <= S.AWH",
      "action": "Set S.GSR, S.ISR, S.SWL, S.SWH",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type != Response and P.type != Reset",
      "action": "Generate Reset(Packet Error)",
      "to": "REQUEST"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Response",
      "action": "S.state := PARTOPEN, Set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "P.type == Request",
      "action": "Send Response, possibly containing Init Cookie, Destroy S",
      "to": "LISTEN"
    },
    {
      "from": "RESPOND",
      "event": "P.type != Request",
      "action": "S.OSR := P.seqno, S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type == Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type != Sync",
      "action": "S.OSR := P.seqno, S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "OPEN",
      "event": "P.type == CloseReq",
      "action": "Generate Close, S.state := CLOSING, Set CLOSING timer",
      "to": "CLOSING"
    },
    {
      "from": "CLOSING",
      "event": "P.type == Close",
      "action": "Generate Reset(Closed), Tear down connection",
      "to": "TIMEWAIT"
    },
    {
      "from": "TIMEWAIT",
      "event": "P.type != Reset",
      "action": "Generate Reset(No Connection)",
      "to": "TIMEWAIT"
    }
  ]
}

